from pipeline import ROOT,OUT,LABELS
m=json.loads((OUT/'metrics.json').read_text()); p=json.loads((OUT/'predictions.json').read_text()); n=pd.read_csv(OUT/'per_person_sleep.csv').to_dict('records'); d=json.loads((OUT/'diagnostics.json').read_text()); failures=json.loads((OUT/'failure_gallery.json').read_text());release=json.loads((OUT/'release/metrics.json').read_text())
